#!/usr/bin/env python3
"""Offline launcher for exploratory fix2 checkpoint Test878. No network required."""
import base64
import hashlib
import io
import json
import os
from pathlib import Path
import sys
import tempfile
import zipfile

PAYLOAD_SHA256 = '4a8983944cc5535d9e6cabe890cd074273849303d13a4298704f2e4d5a7395f7'
PAYLOAD = ''

def main():
    data = base64.b64decode(PAYLOAD, validate=True)
    if hashlib.sha256(data).hexdigest() != PAYLOAD_SHA256:
        raise SystemExit("Embedded Test ZIP checksum failed")
    root = Path(tempfile.mkdtemp(prefix="soft_memory_test_v2_fix1_", dir=Path(__file__).resolve().parent))
    with zipfile.ZipFile(io.BytesIO(data)) as z:
        for member in z.infolist():
            relative = Path(member.filename)
            destination = root / relative
            if relative.is_absolute() or ".." in relative.parts or not destination.resolve().is_relative_to(root):
                raise SystemExit("Unsafe embedded package member")
            if member.is_dir():
                destination.mkdir(parents=True, exist_ok=True)
            else:
                destination.parent.mkdir(parents=True, exist_ok=True)
                with destination.open("xb") as handle:
                    handle.write(z.read(member))
    tool = root / "soft_memory_q_rebased_test_v2_fix1"
    hashes = json.loads((tool / "SHA256SUMS.json").read_text())
    for name, expected in hashes.items():
        if Path(name).name != name or hashlib.sha256((tool/name).read_bytes()).hexdigest() != expected:
            raise SystemExit("Extracted Test file checksum failed: " + name)
    print("TEST_TOOL_DIR=" + str(tool), flush=True)
    os.execv(sys.executable, [sys.executable, "-u", str(tool / "start.py"), *sys.argv[1:]])

if __name__ == "__main__":
    main()
